-- articles DDL
CREATE SEQUENCE IF NOT EXISTS "articles_id_seq";
CREATE TABLE "articles" (
"id" int4 NOT NULL DEFAULT nextval('articles_id_seq'::regclass),
"article_id" varchar(32) NOT NULL,
"title" varchar(512) NOT NULL,
"summary" text NOT NULL,
"source" varchar(64) NOT NULL,
"source_url" text NOT NULL,
"topic" varchar(64) NOT NULL,
"cover" text NOT NULL,
"stars" int4 NOT NULL,
"word_count" int4 NOT NULL,
"segment_count" int4 NOT NULL,
"status" varchar(16) NOT NULL,
"is_free_preview" bool NOT NULL,
"published_at" timestamp(6),
"created_at" timestamp(6) NOT NULL,
"updated_at" timestamp(6) NOT NULL,
"tts_status" varchar(16) NOT NULL DEFAULT 'none'::character varying,
CONSTRAINT "articles_pkey" PRIMARY KEY ("id"));

-- user_article_favorites DDL
CREATE TABLE "user_article_favorites" (
"user_id" int4 NOT NULL,
"article_id" int4 NOT NULL,
"created_at" timestamp(6) NOT NULL,
CONSTRAINT "uq_user_article_favorite" PRIMARY KEY ("user_id",
"article_id"));

-- user_article_opens DDL
CREATE SEQUENCE IF NOT EXISTS "user_article_opens_id_seq";
CREATE TABLE "user_article_opens" (
"id" int4 NOT NULL DEFAULT nextval('user_article_opens_id_seq'::regclass),
"user_id" int4,
"device_id" varchar(64) NOT NULL,
"article_id" int4 NOT NULL,
"opened_at" timestamp(6) NOT NULL,
CONSTRAINT "user_article_opens_pkey" PRIMARY KEY ("id"));

-- article_segments DDL
CREATE SEQUENCE IF NOT EXISTS "article_segments_id_seq";
CREATE TABLE "article_segments" (
"id" int4 NOT NULL DEFAULT nextval('article_segments_id_seq'::regclass),
"article_id" int4 NOT NULL,
"index" int4 NOT NULL,
"english" text NOT NULL,
"chinese" text NOT NULL,
"english_html" text NOT NULL,
"audio_url" text NOT NULL DEFAULT ''::text,
"duration_ms" int4 NOT NULL DEFAULT 0,
CONSTRAINT "article_segments_pkey" PRIMARY KEY ("id"));

-- user_article_progress DDL
CREATE SEQUENCE IF NOT EXISTS "user_article_progress_id_seq";
CREATE TABLE "user_article_progress" (
"id" int4 NOT NULL DEFAULT nextval('user_article_progress_id_seq'::regclass),
"user_id" int4 NOT NULL,
"article_id" int4 NOT NULL,
"last_segment_index" int4 NOT NULL,
"max_reached_index" int4 NOT NULL,
"read_time_sec" int4 NOT NULL,
"completion_percent" float8 NOT NULL,
"is_completed" bool NOT NULL,
"first_opened_at" timestamp(6) NOT NULL,
"last_read_at" timestamp(6) NOT NULL,
"completed_at" timestamp(6),
CONSTRAINT "user_article_progress_pkey" PRIMARY KEY ("id"));

-- articles Constraints
CREATE UNIQUE INDEX "ix_articles_article_id" ON "articles" USING btree ("article_id" COLLATE "pg_catalog"."default" "pg_catalog"."text_ops" ASC NULLS LAST);

-- user_article_favorites Constraints
ALTER TABLE "user_article_favorites" ADD CONSTRAINT "user_article_favorites_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "public"."users" ("id")ON DELETE NO ACTION ON UPDATE NO ACTION;
ALTER TABLE "user_article_favorites" ADD CONSTRAINT "user_article_favorites_article_id_fkey" FOREIGN KEY ("article_id") REFERENCES "public"."articles" ("id")ON DELETE NO ACTION ON UPDATE NO ACTION;

-- user_article_opens Constraints
CREATE INDEX "ix_user_article_opens_article_id" ON "user_article_opens" USING btree ("article_id"  "pg_catalog"."int4_ops" ASC NULLS LAST);
CREATE INDEX "ix_user_article_opens_device_id" ON "user_article_opens" USING btree ("device_id" COLLATE "pg_catalog"."default" "pg_catalog"."text_ops" ASC NULLS LAST);
CREATE INDEX "ix_user_article_opens_user_id" ON "user_article_opens" USING btree ("user_id"  "pg_catalog"."int4_ops" ASC NULLS LAST);
ALTER TABLE "user_article_opens" ADD CONSTRAINT "user_article_opens_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "public"."users" ("id")ON DELETE NO ACTION ON UPDATE NO ACTION;
ALTER TABLE "user_article_opens" ADD CONSTRAINT "user_article_opens_article_id_fkey" FOREIGN KEY ("article_id") REFERENCES "public"."articles" ("id")ON DELETE NO ACTION ON UPDATE NO ACTION;

-- article_segments Constraints
CREATE INDEX "ix_article_segments_article_id" ON "article_segments" USING btree ("article_id"  "pg_catalog"."int4_ops" ASC NULLS LAST);
CREATE UNIQUE INDEX "uq_article_segment_index" ON "article_segments" USING btree ("article_id"  "pg_catalog"."int4_ops" ASC NULLS LAST,"index"  "pg_catalog"."int4_ops" ASC NULLS LAST);
ALTER TABLE "article_segments" ADD CONSTRAINT "article_segments_article_id_fkey" FOREIGN KEY ("article_id") REFERENCES "public"."articles" ("id")ON DELETE NO ACTION ON UPDATE NO ACTION;

-- user_article_progress Constraints
CREATE INDEX "ix_user_article_progress_article_id" ON "user_article_progress" USING btree ("article_id"  "pg_catalog"."int4_ops" ASC NULLS LAST);
CREATE INDEX "ix_user_article_progress_user_id" ON "user_article_progress" USING btree ("user_id"  "pg_catalog"."int4_ops" ASC NULLS LAST);
CREATE UNIQUE INDEX "uq_user_article_progress" ON "user_article_progress" USING btree ("user_id"  "pg_catalog"."int4_ops" ASC NULLS LAST,"article_id"  "pg_catalog"."int4_ops" ASC NULLS LAST);
ALTER TABLE "user_article_progress" ADD CONSTRAINT "user_article_progress_user_id_fkey" FOREIGN KEY ("user_id") REFERENCES "public"."users" ("id")ON DELETE NO ACTION ON UPDATE NO ACTION;
ALTER TABLE "user_article_progress" ADD CONSTRAINT "user_article_progress_article_id_fkey" FOREIGN KEY ("article_id") REFERENCES "public"."articles" ("id")ON DELETE NO ACTION ON UPDATE NO ACTION;

