INSERT INTO "articles" ("id","article_id","title","summary","source","source_url","topic","cover","stars","word_count","segment_count","status","is_free_preview","published_at","created_at","updated_at","tts_status") VALUES (1,'RMVm_F-btmyczxo','Hong Kong Ballet unveils dazzling stage lineup','','China Daily','','','',4,598,37,'published',false,'2026-07-06 12:15:44','2026-07-06 12:11:41','2026-07-06 14:54:41','ready');
