-- article_segments DML
INSERT INTO "article_segments" ("id","article_id","index","english","chinese","english_html","audio_url","duration_ms") VALUES (121,1,9,'"Hotpot is more than a meal; it is a living expression of togetherness and community," Webre says.','“火锅不仅仅是一顿饭；它是团聚和社区的生活表达，”Webre说。','<span tid="50026" class="highlight highlight-a">"Hotpot</span><span>is</span><span pid="512" class="highlight highlight-c">more than</span><span>a</span><span>meal;</span><span>it</span><span>is</span><span>a</span><span tid="50027" class="highlight highlight-a">living</span><span tid="50028" class="highlight highlight-a">expression</span><span>of</span><span tid="50029" class="highlight highlight-a">togetherness</span><span>and</span><span>community,"</span><span>Webre</span><span>says.</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0009.mp3',6800),(128,1,16,'an original score that fuses orchestral music with Chinese instruments and contemporary pop, and designs by Oscar-winning art director Tim Yip.','配乐融合了管弦乐、中国乐器和当代流行音乐，并由奥斯卡获奖艺术总监叶锦添设计。','<span>an</span><span tid="50057" class="highlight highlight-a">original</span><span tid="50058" class="highlight highlight-a">score</span><span>that</span><span tid="50059" class="highlight highlight-a">fuses</span><span tid="50060" class="highlight highlight-a">orchestral</span><span>music</span><span>with</span><span>Chinese</span><span tid="50061" class="highlight highlight-a">instruments</span><span>and</span><span tid="50062" class="highlight highlight-a">contemporary</span><span tid="50063" class="highlight highlight-a">pop</span><span>,</span><span>and</span><span tid="50064" class="highlight highlight-a">designs</span><span>by</span><span tid="50065" class="highlight highlight-a">Oscar-winning</span><span>art</span><span>director</span><span>Tim</span><span>Yip</span><span>.</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0016.mp3',8800),(130,1,18,'Inspired by the novel Siddhartha by German-born Swiss writer Hermann Hesse, who received the Nobel Prize in Literature in 1946,','受1946年诺贝尔文学奖得主、德裔瑞士作家赫尔曼·黑塞的小说《悉达多》启发，','<span tid="50071" class="highlight highlight-a">Inspired</span><span>by</span><span>the</span><span tid="50072" class="highlight highlight-a">novel</span><span>Siddhartha</span><span>by</span><span tid="50073" class="highlight highlight-a">German-born</span><span>Swiss</span><span>writer</span><span>Hermann</span><span>Hesse</span><span>,</span><span>who</span><span>received</span><span>the</span><span>Nobel</span><span>Prize</span><span>in</span><span>Literature</span><span>in</span><span>1946</span><span>,</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0018.mp3',8000),(112,1,0,'Hotpot, neon lights, kung fu cinema, and high fashion are not the ingredients one would typically associate with classical ballet.','火锅、霓虹灯、功夫电影和高级时装并不是人们通常与古典芭蕾联系在一起的元素。','<span tid="50001" class="highlight highlight-a">Hotpot</span><span>,</span><span pid="501" class="highlight highlight-a">neon lights</span><span>,</span><span pid="502" class="highlight highlight-a">kung fu cinema</span><span>,</span><span>and</span><span pid="503" class="highlight highlight-a">high fashion</span><span>are</span><span>not</span><span>the</span><span tid="50002" class="highlight highlight-a">ingredients</span><span>one</span><span>would</span><span>typically</span><span tid="50003" class="highlight highlight-a">associate</span><span>with</span><span pid="504" class="highlight highlight-a">classical ballet</span><span>.</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0000.mp3',8000),(113,1,1,'Yet, the Hong Kong Ballet is blending them into an exuberant celebration of the city''s cultural identity with the launch of its 2026/27 season,','然而，香港芭蕾舞团正通过推出2026/27演出季，将这些元素融合成一场对城市文化身份的欢庆，','<span>Yet</span><span>,</span><span>the</span><span pid="505" class="highlight highlight-a">Hong Kong Ballet</span><span>is</span><span tid="50004" class="highlight highlight-a">blending</span><span>them</span><span>into</span><span>an</span><span tid="50005" class="highlight highlight-a">exuberant</span><span tid="50006" class="highlight highlight-a">celebration</span><span>of</span><span>the</span><span>city''s</span><span pid="506" class="highlight highlight-a">cultural identity</span><span>with</span><span>the</span><span tid="50007" class="highlight highlight-a">launch</span><span>of</span><span>its</span><span>2026/27 season</span><span>,</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0001.mp3',9200),(114,1,2,'aptly titled Hong Kong Bling.','恰如其分地命名为“香港闪耀”。','<span tid="50008" class="highlight highlight-a">aptly</span><span>titled</span><span pid="507" class="highlight highlight-a">Hong Kong Bling</span><span>.</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0002.mp3',2000),(115,1,3,'Drawing inspiration from Hong Kong''s vibrant 1970s heyday, when film, music and fashion flourished with global influence,','从香港充满活力的1970年代鼎盛时期汲取灵感，当时电影、音乐和时尚蓬勃发展，具有全球影响力，','<span pid="508" class="highlight highlight-c">Drawing inspiration from</span><span>Hong Kong''s</span><span tid="50009" class="highlight highlight-a">vibrant</span><span>1970s</span><span tid="50010" class="highlight highlight-a">heyday</span><span>,</span><span>when</span><span>film</span><span>,</span><span>music</span><span>and</span><span>fashion</span><span tid="50011" class="highlight highlight-a">flourished</span><span>with</span><span pid="509" class="highlight highlight-a">global influence</span><span>,</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0003.mp3',6800),(116,1,4,'the new season is set to bring an eclectic mix of world premieres,','新演出季将带来一系列世界首演、获奖作品和社区活动，','<span>the</span><span>new</span><span>season</span><span pid="510" class="highlight highlight-c">is set to</span><span>bring</span><span>an</span><span tid="50012" class="highlight highlight-a">eclectic</span><span>mix</span><span>of</span><span tid="50013" class="highlight highlight-a">world premieres,</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0004.mp3',5200),(117,1,5,'award-winning productions and community initiatives that reflect both the city''s rich heritage and its contemporary creative energy.','既反映城市丰富的遗产，也体现其当代的创意活力。','<span tid="50014" class="highlight highlight-a">award-winning</span><span>productions</span><span>and</span><span>community</span><span tid="50015" class="highlight highlight-a">initiatives</span><span>that</span><span>reflect</span><span>both</span><span>the</span><span>city''s</span><span>rich</span><span tid="50016" class="highlight highlight-a">heritage</span><span>and</span><span>its</span><span tid="50017" class="highlight highlight-a">contemporary</span><span>creative</span><span>energy.</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0005.mp3',7200),(118,1,6,'The program was unveiled on June 23.','该节目于6月23日揭晓。','<span>The</span><span>program</span><span>was</span><span tid="50018" class="highlight highlight-a">unveiled</span><span>on</span><span>June</span><span>23.</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0006.mp3',2400),(119,1,7,'Artistic director Septime Webre describes the upcoming season as a theatrical hotpot,','艺术总监Septime Webre将即将到来的演出季描述为一场戏剧火锅，','<span>Artistic</span><span>director</span><span>Septime</span><span>Webre</span><span>describes</span><span>the</span><span>upcoming</span><span>season</span><span>as</span><span>a</span><span tid="50019" class="highlight highlight-a">theatrical</span><span tid="50020" class="highlight highlight-a">hotpot,</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0007.mp3',4800),(120,1,8,'where diverse cultural influences come together to create something greater than the sum of their parts.','不同的文化影响汇聚在一起，创造出比各部分之和更伟大的东西。','<span>where</span><span tid="50021" class="highlight highlight-a">diverse</span><span tid="50022" class="highlight highlight-a">cultural</span><span tid="50023" class="highlight highlight-a">influences</span><span pid="511" class="highlight highlight-d">come together</span><span>to</span><span>create</span><span>something</span><span tid="50024" class="highlight highlight-a">greater</span><span>than</span><span>the</span><span tid="50025" class="highlight highlight-a">sum</span><span>of</span><span>their</span><span>parts.</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0008.mp3',6400),(122,1,10,'"Generations of family and friends have transformed individual ingredients into something greater and richer, enjoyed around the table together."','“几代家人和朋友将个人食材转化为更伟大、更丰富的东西，一起围坐在桌旁享用。”','<span tid="50030" class="highlight highlight-a">"Generations</span><span>of</span><span>family</span><span>and</span><span>friends</span><span>have</span><span tid="50031" class="highlight highlight-a">transformed</span><span tid="50032" class="highlight highlight-a">individual</span><span tid="50033" class="highlight highlight-a">ingredients</span><span>into</span><span>something</span><span tid="50034" class="highlight highlight-a">greater</span><span>and</span><span tid="50035" class="highlight highlight-a">richer,</span><span>enjoyed</span><span>around</span><span>the</span><span>table</span><span>together."</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0010.mp3',7600),(123,1,11,'He likened the company''s new season to that communal dining experience, combining the glamour of 1970s Hong Kong —','他将舞团的新演出季比作那种共享的用餐体验，将1970年代香港的魅力——','<span>He</span><span tid="50036" class="highlight highlight-a">likened</span><span>the</span><span>company''s</span><span>new</span><span>season</span><span>to</span><span>that</span><span tid="50037" class="highlight highlight-a">communal</span><span>dining</span><span>experience,</span><span>combining</span><span>the</span><span tid="50038" class="highlight highlight-a">glamour</span><span>of</span><span>1970s</span><span>Hong</span><span>Kong</span><span>—</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0011.mp3',7200),(124,1,12,'from glitzy disco culture and neon-lit streets to martial arts films and bold fashion — into "something memorable and meaningful".','从耀眼的迪斯科文化和霓虹灯街道到武侠电影和大胆的时尚——融合成“令人难忘且有意义的东西”。','<span>from</span><span tid="50039" class="highlight highlight-a">glitzy</span><span>disco</span><span>culture</span><span>and</span><span tid="50040" class="highlight highlight-a">neon-lit</span><span>streets</span><span>to</span><span tid="50041" class="highlight highlight-a">martial</span><span>arts</span><span>films</span><span>and</span><span tid="50042" class="highlight highlight-a">bold</span><span>fashion</span><span>—</span><span>into</span><span>"something</span><span tid="50043" class="highlight highlight-a">memorable</span><span>and</span><span tid="50044" class="highlight highlight-a">meaningful".</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0012.mp3',8000),(125,1,13,'The centerpiece of the season is an ambitious trio of productions exploring identity, transformation and human resilience.','该演出季的核心是一组雄心勃勃的三部作品，探索身份、转变和人类韧性。','<span>The</span><span tid="50045" class="highlight highlight-a">centerpiece</span><span>of</span><span>the</span><span>season</span><span>is</span><span>an</span><span tid="50046" class="highlight highlight-a">ambitious</span><span tid="50047" class="highlight highlight-a">trio</span><span>of</span><span>productions</span><span>exploring</span><span tid="50048" class="highlight highlight-a">identity,</span><span tid="50049" class="highlight highlight-a">transformation</span><span>and</span><span>human</span><span tid="50050" class="highlight highlight-a">resilience.</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0013.mp3',6800),(126,1,14,'Among them is the world premiere of Bruce Lee: Hong Kong Legend, created and directed by Webre.','其中包括由Webre创作和执导的世界首演《李小龙：香港传奇》。','<span>Among</span><span>them</span><span>is</span><span>the</span><span>world</span><span tid="50051" class="highlight highlight-a">premiere</span><span>of</span><span>Bruce</span><span>Lee:</span><span>Hong</span><span>Kong</span><span>Legend,</span><span>created</span><span>and</span><span>directed</span><span>by</span><span>Webre.</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0014.mp3',6800),(127,1,15,'The large-scale production celebrates the martial arts icon through ballet, blending classical dance with action choreography,','这部大型作品通过芭蕾舞庆祝这位武术偶像，将古典舞蹈与动作编排相结合，','<span>The</span><span tid="50052" class="highlight highlight-a">large-scale</span><span>production</span><span>celebrates</span><span>the</span><span tid="50053" class="highlight highlight-a">martial</span><span>arts</span><span tid="50054" class="highlight highlight-a">icon</span><span>through</span><span>ballet,</span><span>blending</span><span tid="50055" class="highlight highlight-a">classical</span><span>dance</span><span>with</span><span>action</span><span tid="50056" class="highlight highlight-a">choreography,</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0015.mp3',6800),(129,1,17,'Another major premiere, Dunhuang: In Search of Light, reunites choreographer Hu Song Wei Ricky and Mai Jingwen.','另一部重要首演《敦煌：寻光之旅》由编舞家胡颂威和麦静雯再度合作。','<span>Another</span><span tid="50066" class="highlight highlight-a">major</span><span tid="50067" class="highlight highlight-a">premiere</span><span>,</span><span>Dunhuang</span><span>:</span><span>In</span><span tid="50068" class="highlight highlight-a">Search</span><span>of</span><span>Light</span><span>,</span><span tid="50069" class="highlight highlight-a">reunites</span><span tid="50070" class="highlight highlight-a">choreographer</span><span>Hu</span><span>Song</span><span>Wei</span><span>Ricky</span><span>and</span><span>Mai</span><span>Jingwen</span><span>.</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0017.mp3',6800),(131,1,19,'and the ancient grottoes in Dunhuang, the production follows a young man''s spiritual journey toward enlightenment, combining classical ballet with immersive visual storytelling.','以及敦煌的古老石窟，该作品讲述了一个年轻人走向 enlightenment 的精神旅程，将古典芭蕾与沉浸式视觉叙事相结合。','<span>and</span><span>the</span><span tid="50074" class="highlight highlight-a">ancient</span><span tid="50075" class="highlight highlight-a">grottoes</span><span>in</span><span>Dunhuang</span><span>,</span><span>the</span><span tid="50076" class="highlight highlight-a">production</span><span>follows</span><span>a</span><span>young</span><span>man</span><span>''s</span><span tid="50077" class="highlight highlight-a">spiritual</span><span tid="50078" class="highlight highlight-a">journey</span><span>toward</span><span tid="50079" class="highlight highlight-a">enlightenment</span><span>,</span><span tid="50080" class="highlight highlight-a">combining</span><span tid="50081" class="highlight highlight-a">classical</span><span tid="50082" class="highlight highlight-a">ballet</span><span>with</span><span tid="50083" class="highlight highlight-a">immersive</span><span>visual</span><span tid="50084" class="highlight highlight-a">storytelling</span><span>.</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0019.mp3',9200),(132,1,20,'It also marks the Hong Kong Ballet''s first collaboration with the Dunhuang Academy in Gansu province.','这也标志着香港芭蕾舞团与甘肃省敦煌研究院的首次合作。','<span>It</span><span>also</span><span tid="50085" class="highlight highlight-a">marks</span><span>the</span><span>Hong</span><span>Kong</span><span>Ballet</span><span>''s</span><span>first</span><span tid="50086" class="highlight highlight-a">collaboration</span><span>with</span><span>the</span><span>Dunhuang</span><span tid="50087" class="highlight highlight-a">Academy</span><span>in</span><span>Gansu</span><span>province</span><span>.</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0020.mp3',6400),(133,1,21,'Another highlight is Coco Chanel: The Life of a Fashion Icon, choreographed by Annabelle Lopez Ochoa.','另一个亮点是由Annabelle Lopez Ochoa编舞的《可可·香奈儿：时尚偶像的一生》。','<span>Another</span><span tid="50088" class="highlight highlight-a">highlight</span><span>is</span><span>Coco</span><span>Chanel</span><span>:</span><span>The</span><span>Life</span><span>of</span><span>a</span><span>Fashion</span><span tid="50089" class="highlight highlight-a">Icon</span><span>,</span><span tid="50090" class="highlight highlight-a">choreographed</span><span>by</span><span>Annabelle</span><span>Lopez</span><span>Ochoa</span><span>.</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0021.mp3',6400),(134,1,22,'The ballet examines the complicated life and legacy of the designer whose influence reshaped the fashion world.','这部芭蕾舞剧审视了这位设计师复杂的生活和遗产，她的影响力重塑了时尚界。','<span>The</span><span tid="50091" class="highlight highlight-a">ballet</span><span tid="50092" class="highlight highlight-a">examines</span><span>the</span><span tid="50093" class="highlight highlight-a">complicated</span><span>life</span><span>and</span><span tid="50094" class="highlight highlight-a">legacy</span><span>of</span><span>the</span><span tid="50095" class="highlight highlight-a">designer</span><span>whose</span><span tid="50096" class="highlight highlight-a">influence</span><span tid="50097" class="highlight highlight-a">reshaped</span><span>the</span><span>fashion</span><span>world</span><span>.</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0022.mp3',6800),(135,1,23,'Classical favorites also remain firmly on the menu.','古典经典也仍然在菜单上。','<span tid="50098" class="highlight highlight-a">Classical</span><span tid="50099" class="highlight highlight-a">favorites</span><span>also</span><span>remain</span><span tid="50100" class="highlight highlight-a">firmly</span><span>on</span><span>the</span><span tid="50101" class="highlight highlight-a">menu</span><span>.</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0023.mp3',3200),(136,1,24,'Audiences can look forward to the return of The Nutcracker, Webre''s interpretation of the classic, as well as the swashbuckling Le Corsaire: The Pirate Hunter!,','观众可以期待《胡桃夹子》的回归，即Webre对经典作品的诠释，以及充满冒险精神的《海盗：猎海盗！》，','<span>Audiences</span><span>can</span><span>look</span><span>forward</span><span>to</span><span>the</span><span>return</span><span>of</span><span>The</span><span>Nutcracker,</span><span>Webre''s</span><span>interpretation</span><span>of</span><span>the</span><span>classic,</span><span>as</span><span>well</span><span>as</span><span>the</span><span>swashbuckling</span><span>Le</span><span>Corsaire:</span><span>The</span><span>Pirate</span><span>Hunter!,</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0024.mp3',10000),(137,1,25,'known for its athletic choreography and spectacular stagecraft.','以其运动型编舞和壮观的舞台效果而闻名。','<span>known</span><span>for</span><span>its</span><span tid="50102" class="highlight highlight-a">athletic</span><span tid="50103" class="highlight highlight-a">choreography</span><span>and</span><span tid="50104" class="highlight highlight-a">spectacular</span><span tid="50105" class="highlight highlight-a">stagecraft</span><span>.</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0025.mp3',3200),(138,1,26,'Families are also catered for through Summer Fling, an interactive studio event featuring excerpts from the company''s repertoire,','家庭也可以通过《夏日狂欢》得到满足，这是一个互动工作室活动，包括舞团剧目的片段，','<span>Families</span><span pid="513" class="highlight highlight-d">are also catered for</span><span>through</span><span>Summer Fling</span><span>,</span><span>an</span><span tid="50106" class="highlight highlight-a">interactive</span><span>studio</span><span>event</span><span tid="50107" class="highlight highlight-a">featuring</span><span tid="50108" class="highlight highlight-a">excerpts</span><span>from</span><span>the</span><span>company</span><span>''s</span><span tid="50109" class="highlight highlight-a">repertoire</span><span>,</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0026.mp3',7200),(139,1,27,'opportunities to meet dancers and ballet workshops for children.','与舞者见面的机会以及儿童芭蕾工作坊。','<span tid="50110" class="highlight highlight-a">opportunities</span><span>to meet</span><span>dancers</span><span>and</span><span>ballet</span><span>workshops</span><span>for</span><span>children</span><span>.</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0027.mp3',3600),(140,1,28,'Beyond the stage, the Hong Kong Ballet continues to strengthen its role as one of the city''s cultural ambassadors.','在舞台之外，香港芭蕾舞团继续加强其作为城市文化大使之一的角色。','<span tid="50111" class="highlight highlight-c">Beyond</span><span>the</span><span>stage</span><span>,</span><span>the</span><span>Hong Kong Ballet</span><span>continues</span><span pid="514" class="highlight highlight-a">to strengthen</span><span>its</span><span>role</span><span>as</span><span pid="515" class="highlight highlight-c">one of</span><span>the</span><span>city</span><span>''s</span><span tid="50112" class="highlight highlight-a">cultural</span><span tid="50113" class="highlight highlight-a">ambassadors</span><span>.</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0028.mp3',7600),(141,1,29,'Its internationally acclaimed Romeo + Juliet, set in 1960s Hong Kong, will tour Beijing in August and Chengdu, Sichuan province, in September,','其国际获奖作品《罗密欧+朱丽叶》以1960年代的香港为背景，将于8月在北京巡演，9月在四川成都巡演，','<span>Its</span><span tid="50114" class="highlight highlight-a">internationally</span><span tid="50115" class="highlight highlight-a">acclaimed</span><span>Romeo + Juliet</span><span>,</span><span pid="516" class="highlight highlight-d">set in</span><span>1960s</span><span>Hong Kong</span><span>,</span><span pid="517" class="highlight highlight-a">will tour</span><span>Beijing</span><span>in</span><span>August</span><span>and</span><span>Chengdu</span><span>,</span><span>Sichuan province</span><span>,</span><span>in</span><span>September</span><span>,</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0029.mp3',8400),(142,1,30,'following performances in New York, London and Seoul.','此前已在纽约、伦敦和首尔演出。','<span>following</span><span>performances</span><span>in</span><span>New York</span><span>,</span><span>London</span><span>and</span><span>Seoul</span><span>.</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0030.mp3',3200),(143,1,31,'Webre highlights the company''s expanding community outreach, including the growth of the Hong Kong Academy of Ballet,','Webre强调了舞团不断扩大的社区外展活动，包括香港芭蕾舞学院的成长，','<span>Webre</span><span tid="50116" class="highlight highlight-a">highlights</span><span>the</span><span>company</span><span>''s</span><span tid="50117" class="highlight highlight-a">expanding</span><span>community</span><span tid="50118" class="highlight highlight-a">outreach</span><span>,</span><span>including</span><span>the</span><span>growth</span><span>of</span><span>the</span><span>Hong Kong Academy of Ballet</span><span>,</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0031.mp3',6800),(144,1,32,'its "Dancing to Hong Kong''s Heartbeat" initiative and "Silver Ballet" programs designed for seniors.','其“舞动香港心跳”倡议和为老年人设计的“银发芭蕾”项目。','<span>its</span><span pid="518" class="highlight highlight-i">"Dancing to Hong Kong''s Heartbeat"</span><span tid="50119" class="highlight highlight-a">initiative</span><span>and</span><span pid="519" class="highlight highlight-i">"Silver Ballet"</span><span>programs</span><span tid="50120" class="highlight highlight-a">designed</span><span>for</span><span>seniors.</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0032.mp3',5600),(145,1,33,'More pop-up performances and collaborations across the Guangdong-Hong Kong-Macao Greater Bay Area are planned for 2027.','计划在2027年举办更多粤港澳大湾区的快闪表演和合作。','<span>More</span><span pid="520" class="highlight highlight-a">pop-up</span><span tid="50121" class="highlight highlight-a">performances</span><span>and</span><span tid="50122" class="highlight highlight-a">collaborations</span><span>across</span><span>the</span><span pid="521" class="highlight highlight-a">Guangdong-Hong Kong-Macao Greater Bay Area</span><span>are</span><span tid="50123" class="highlight highlight-a">planned</span><span>for</span><span>2027.</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0033.mp3',7200),(146,1,34,'"Just as we gather together to share meals,','“就像我们聚在一起分享美食一样，','<span>"Just</span><span>as</span><span>we</span><span tid="50124" class="highlight highlight-a">gather</span><span>together</span><span>to</span><span>share</span><span>meals,</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0034.mp3',3200),(147,1,35,'we can gather at the theater and in the community to experience creativity and artistry that reflects the Hong Kong Ballet today," Webre says.','我们也可以在剧院和社区中聚集，体验反映当今香港芭蕾舞团的创造力和艺术，”Webre说。','<span>we</span><span>can</span><span tid="50125" class="highlight highlight-a">gather</span><span>at</span><span>the</span><span>theater</span><span>and</span><span>in</span><span>the</span><span>community</span><span>to</span><span tid="50126" class="highlight highlight-a">experience</span><span tid="50127" class="highlight highlight-a">creativity</span><span>and</span><span tid="50128" class="highlight highlight-a">artistry</span><span>that</span><span tid="50129" class="highlight highlight-a">reflects</span><span>the</span><span pid="522" class="highlight highlight-a">Hong Kong Ballet</span><span>today,"</span><span>Webre</span><span>says.</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0035.mp3',9600),(148,1,36,'"It''s rooted in tradition yet boldly contemporary, stylish and deeply connected to both the city and the world."','“它植根于传统，但又大胆现代，时尚且与城市和世界紧密相连。”','<span>"It''s</span><span tid="50130" class="highlight highlight-a">rooted</span><span>in</span><span tid="50131" class="highlight highlight-a">tradition</span><span>yet</span><span tid="50132" class="highlight highlight-a">boldly</span><span tid="50133" class="highlight highlight-a">contemporary,</span><span tid="50134" class="highlight highlight-a">stylish</span><span>and</span><span>deeply</span><span tid="50135" class="highlight highlight-a">connected</span><span>to</span><span>both</span><span>the</span><span>city</span><span>and</span><span>the</span><span>world."</span>','http://oss.sxakgs.com/en/reading/RMVm_F-btmyczxo/seg_0036.mp3',7200);
